from pathlib import Path
import json,statistics
R=Path(__file__).resolve().parent;b=json.loads((R/'BENCHMARK.json').read_text());c=json.loads((R/'COSTS.json').read_text())
lines=['# Fixed-four-block cache measured ordered host benchmark','','All 87 fixture pins and all compiled-source pins verified before and after. Each scenario uses all 40 frames, 1,296,000 full row-major pixels. One empty-start warmup plus nine independent trials, rotating/reversing sequential arm order. Cache binding/index validation and resets are included in primary batch wall time. Pixel-only and setup-only intervals are retained separately. Host was coordinated against known tests, not reserved against unrelated load. No device or full-renderer speed claim.','','## Primary setup-inclusive wall time','','| Scenario | Raw ns/profile | Baseline | Gather | Cache4 | Cache4 speedup vs gather | Cache4/raw |','|---|---:|---:|---:|---:|---:|---:|']
for name,s in b['scenarios'].items():
 v=s['primaryNsPerProfile'];lines.append(f"| {name} | {v['raw']:.3f} | {v['baseline']:.3f} | {v['gather']:.3f} | {v['cache4']:.3f} | {v['gather']/v['cache4']:.3f}x | {v['cache4']/v['raw']:.3f}x |")
lines+=['','## Setup, actual cache counters and shared-host variation','']
for name,s in b['scenarios'].items():
 a=[t['arms']['cache4'] for t in s['trials']];counts={tuple(x['counterTotals']) for x in a};assert len(counts)==1
 h,m,i=next(iter(counts));lo=min(x['batchWallNs'] for x in a)/1e6;hi=max(x['batchWallNs'] for x in a)/1e6
 lines.append(f"- {name}: actual hits {h:,}, misses {m:,}, invalidations {i:,}; hit rate {h/(h+m)*100:.4f}%. Median total setup {s['medians']['setupNs']['cache4']/1e6:.4f} ms; median pixel-only {s['medians']['pixelNs']['cache4']/1e6:.3f} ms. Cache batch wall range {lo:.3f}–{hi:.3f} ms across nine trials.")
lines+=['','Misses on these successful fixed-data evaluations correspond to decoded blocks. Evictions/encoded bytes/decoded symbols are not instrumented, so no measured values are claimed. Counters are enabled in timing. Cold-per-frame rebinds and fully validates the index every frame; warm-across-frame binds once per trial and starts empty, never retaining warmup/trial state. Primary batch wall also includes Python dispatch and counter snapshots, with the exact gap recorded in BENCHMARK.json.','', '## Measured object and storage costs','','| Arm | Text B | Read-only B | Writable static B | Caller cache sizeof B | Conservative stack chain B |','|---|---:|---:|---:|---:|---:|']
for name,a in c['arms'].items():lines.append(f"| {name} | {a['text']} | {a['readOnlyData']} | {a['writableStatic']} | {a['callerCacheSizeofBytes']} | {a['conservativeProfileDecoderCallChainBytes']} |")
lines+=['',c['scope'],'','The cache includes encoded snapshots to check mutable-input freshness in addition to 1536 B of decoded values. Binding performs full index validation; per-evaluation checks and hit snapshot comparisons are included. Heap allocation is absent.','','## Evidence and reproduction','','BUILD.json records flags/compiler/source pins; COSTS.json and build/*.su/size.txt record object/stack evidence. BENCHMARK.json retains every warmup, trial, frame time, setup time, checksum, actual counter delta, binary/input hashes and start/end host snapshots. Exact correctness and lifecycle evidence lives in the independently owned tests directory. Checksum parity is supplementary only. Run build.py, costs.py, then benchmark_ordered.py --quiet-window-approved only after correctness and coordinated test-idle approval, followed by report.py. Share only BUNDLE_ALLOWLIST entries, never private inputs or linked data-bearing binaries.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
